import random

import threading

from six.moves import socketserver
from .util import RetryWhenSocketError


class ForwardServer(threading.Thread, socketserver.ThreadingTCPServer):
    """
    Class handles TCP connections and is used to encapsulate local SSH connection and send it to destination.

    .. code-block:: python

        server = ForwardServer(handlers_factory)
        server.start()
        # custom code here
        server.shutdown()
    """
    allow_reuse_address = True
    daemon_threads = True

    def __init__(self, RequestHandlerClass, bind_and_activate=True):
        threading.Thread.__init__(self)
        self.daemon = True
        self._start_server(RequestHandlerClass, bind_and_activate)

    @property
    def port(self):
        """Returns server port."""
        return self._port

    def run(self):
        """Start server."""
        self.serve_forever()

    @RetryWhenSocketError(10)
    def _start_server(self, handler, bind_and_activate):
        self._port = random.randint(10000, 40000)
        socketserver.ThreadingTCPServer.__init__(self, ('', self._port), handler, bind_and_activate)
